const std::array<const char*, 5> drinks = {"Coffee", "Tea", "Milk", "OrangeJuice", "Water"};
const std::array<const char*, 5> pets = {"Dog", "Snail", "Fox", "Horse", "Zebra"};
const std::array<const char*, 5> hobbies = {"Dancing", "Reading", "Painting", "Football", "Chess"};

// Each house stores the index of the value assigned to each attribute,
// or -1 when the attribute has not been assigned yet.
struct House {
    int color = -1;
    int nationality = -1;
    int drink = -1;
    int pet = -1;
    int hobby = -1;
};

bool isAdjacent(int a, int b) { return a + 1 == b || b + 1 == a; }

